import { expect, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test(
    "Documents from another tenant are invisible",
    { tag: "@DOC-07" },
    async ({ apiAs }) => {
      // Arrange: a document exists in tenant "Globex Procurement"
      const globex = await apiAs("otherTenant");
      const vendorResponse = await globex.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Vendor"),
          category: "services",
          contact_email: `billing-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@globex.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();

      const uploadResponse = await globex.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 test document"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Act: a Northwind member requests that document by id
      const member = await apiAs("member");
      const response = await member.get(`/api/documents/${document.id}`);

      // Assert
      expect(response.status()).toBe(404);
      expect((await response.json()).error.code).toBe("document_not_found");
    },
  );
});
